public static void academy() {
    int hallRune = 10;          // visible throughout this method
    if (hallRune > 5) {
        int labRune = 20;       // visible only in this if-block
        System.out.println(hallRune); // OK
        System.out.println(labRune);  // OK
    }
    System.out.println(hallRune); // OK
    // System.out.println(labRune); // ERROR: labRune is in the lab only!
}

